import re
import hashlib
import hmac
import os
import time
import urllib.parse
from http.server import BaseHTTPRequestHandler, HTTPServer
from io import BytesIO
import json
import sqlite3
import secrets

# Security configuration
SECRET_KEY = os.environ.get('APP_SECRET', secrets.token_hex(32))
DB_PATH = os.environ.get('DB_PATH', ':memory:')

def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.execute('CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT, display_name TEXT, role TEXT DEFAULT "user", password_hash TEXT)')
    conn.execute('CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id TEXT, created_at REAL, ip TEXT)')
    conn.commit()
    return conn

def constant_time_eq(a, b):
    """Timing-safe string comparison."""
    if isinstance(a, str):
        a = a.encode('utf-8')
    if isinstance(b, str):
        b = b.encode('utf-8')
    return hmac.compare_digest(a, b)

def generate_csrf_token(session_id):
    """Generate CSRF token bound to session."""
    return hmac.new(SECRET_KEY.encode(), session_id.encode(), hashlib.sha256).hexdigest()

def sanitize_header_value(value):
    """Remove control characters to prevent header injection.

    This function prevents HTTP response splitting by removing
    all control characters (CR, LF, null, etc.) that could
    be used to inject additional headers or split responses.
    """
    if not isinstance(value, str):
        value = str(value)
    # Remove ALL control characters (0x00-0x1F and 0x7F)
    # This prevents any form of header injection including
    # lone CR, lone LF, CRLF sequences, and null bytes
    sanitized = re.sub(r'[\x00-\x1f\x7f]', '', value)
    # Strip leading/trailing whitespace
    sanitized = sanitized.strip()
    return sanitized

def validate_redirect_url(url, allowed_hosts):
    """Validate redirect URL against whitelist."""
    try:
        parsed = urllib.parse.urlparse(url)
        if parsed.scheme not in ('https', 'http', ''):
            return None
        if parsed.netloc and parsed.netloc not in allowed_hosts:
            return None
        # Prevent protocol-relative URLs
        if url.startswith('//'):
            return None
        return url
    except Exception:
        return None

class SecureResponseBuilder:
    """Builds HTTP responses with security headers."""

    SECURITY_HEADERS = {
        'X-Content-Type-Options': 'nosniff',
        'X-Frame-Options': 'DENY',
        'X-XSS-Protection': '1; mode=block',
        'Strict-Transport-Security': 'max-age=31536000; includeSubDomains',
        'Content-Security-Policy': "default-src 'self'",
        'Referrer-Policy': 'strict-origin-when-cross-origin',
    }

    def __init__(self):
        self.status_code = 200
        self.headers = dict(self.SECURITY_HEADERS)
        self.body = b''

    def set_status(self, code):
        self.status_code = code
        return self

    def set_header(self, name, value):
        """Set a response header with injection protection."""
        # Validate header name (alphanumeric + hyphen only)
        if not re.match(r'^[A-Za-z][A-Za-z0-9\-]*$', name):
            raise ValueError(f'Invalid header name: {name}')
        # Sanitize header value to prevent response splitting
        safe_value = sanitize_header_value(value)
        self.headers[name] = safe_value
        return self

    def set_cookie(self, name, value, httponly=True, secure=True, samesite='Strict', path='/', max_age=3600):
        """Set a secure cookie."""
        if not re.match(r'^[A-Za-z0-9_\-]+$', name):
            raise ValueError(f'Invalid cookie name: {name}')
        safe_value = sanitize_header_value(value)
        parts = [f'{name}={safe_value}', f'Path={path}', f'Max-Age={max_age}', f'SameSite={samesite}']
        if httponly:
            parts.append('HttpOnly')
        if secure:
            parts.append('Secure')
        cookie_str = '; '.join(parts)
        self.headers.setdefault('Set-Cookie', [])
        if isinstance(self.headers['Set-Cookie'], list):
            self.headers['Set-Cookie'].append(cookie_str)
        else:
            self.headers['Set-Cookie'] = [self.headers['Set-Cookie'], cookie_str]
        return self

    def set_json_body(self, data):
        """Set JSON response body."""
        self.body = json.dumps(data, ensure_ascii=True).encode('utf-8')
        self.headers['Content-Type'] = 'application/json; charset=utf-8'
        return self

    def build_raw(self):
        """Build raw HTTP response bytes."""
        status_line = f'HTTP/1.1 {self.status_code} OK\r\n'
        header_lines = []
        for name, value in self.headers.items():
            if isinstance(value, list):
                for v in value:
                    header_lines.append(f'{name}: {v}\r\n')
            else:
                header_lines.append(f'{name}: {value}\r\n')
        header_lines.append('\r\n')
        response = status_line + ''.join(header_lines)
        return response.encode('utf-8') + self.body


class AppHandler:
    """Application request handler with authentication."""

    ALLOWED_HOSTS = {'example.com', 'www.example.com', 'app.example.com'}

    def __init__(self):
        self.db = get_db()
        self._rate_limits = {}

    def _check_rate_limit(self, ip, limit=60, window=60):
        """Rate limiting per IP."""
        now = time.time()
        key = ip
        if key not in self._rate_limits:
            self._rate_limits[key] = []
        # Clean old entries
        self._rate_limits[key] = [t for t in self._rate_limits[key] if now - t < window]
        if len(self._rate_limits[key]) >= limit:
            return False
        self._rate_limits[key].append(now)
        return True

    def _authenticate(self, token, ip):
        """Validate session token."""
        if not token or not isinstance(token, str):
            return None
        token_hash = hashlib.sha256(token.encode()).hexdigest()
        cursor = self.db.execute(
            'SELECT user_id, ip, created_at FROM sessions WHERE token_hash = ?',
            (token_hash,)
        )
        row = cursor.fetchone()
        if not row:
            return None
        user_id, stored_ip, created_at = row
        # Check session expiry (24 hours)
        if time.time() - created_at > 86400:
            self.db.execute('DELETE FROM sessions WHERE token_hash = ?', (token_hash,))
            self.db.commit()
            return None
        # IP binding
        if stored_ip != ip:
            return None
        return user_id

    def _get_user(self, user_id):
        """Get user from database."""
        cursor = self.db.execute(
            'SELECT id, email, display_name, role FROM users WHERE id = ?',
            (user_id,)
        )
        return cursor.fetchone()

    def _get_password_hash(self, user_id):
        """Fetch the stored password hash for a user."""
        cursor = self.db.execute(
            'SELECT password_hash FROM users WHERE id = ?',
            (user_id,)
        )
        row = cursor.fetchone()
        return row[0] if row else None

    def handle_login(self, username, password_hash, ip):
        """Handle login request."""
        if not self._check_rate_limit(ip, limit=10, window=300):
            return SecureResponseBuilder().set_status(429).set_json_body({'error': 'Rate limited'})

        # Validate input
        if not username or not re.match(r'^[a-zA-Z0-9_]{3,32}$', username):
            return SecureResponseBuilder().set_status(400).set_json_body({'error': 'Invalid username'})

        user = self._get_user(username)
        if not user:
            # Constant-time dummy to prevent enumeration
            hashlib.pbkdf2_hmac('sha256', b'dummy', b'salt', 100000)
            return SecureResponseBuilder().set_status(401).set_json_body({'error': 'Invalid credentials'})

        # Verify supplied credential against the stored password hash
        # in a timing-safe manner. Without this check any valid username
        # would be able to log in without proving knowledge of the secret.
        stored_hash = self._get_password_hash(username)
        if not stored_hash or not isinstance(password_hash, str) or not constant_time_eq(stored_hash, password_hash):
            return SecureResponseBuilder().set_status(401).set_json_body({'error': 'Invalid credentials'})

        # Create session
        token = secrets.token_hex(32)
        token_hash = hashlib.sha256(token.encode()).hexdigest()
        self.db.execute(
            'INSERT INTO sessions (token_hash, user_id, created_at, ip) VALUES (?, ?, ?, ?)',
            (token_hash, username, time.time(), ip)
        )
        self.db.commit()

        response = SecureResponseBuilder()
        response.set_status(200)
        response.set_cookie('session', token)
        response.set_json_body({'status': 'ok', 'user': username})
        return response

    def handle_profile_update(self, token, ip, display_name):
        """Handle profile display name update."""
        user_id = self._authenticate(token, ip)
        if not user_id:
            return SecureResponseBuilder().set_status(401).set_json_body({'error': 'Unauthorized'})

        # Update display name
        if not display_name or len(display_name) > 64:
            return SecureResponseBuilder().set_status(400).set_json_body({'error': 'Invalid display name'})

        self.db.execute(
            'UPDATE users SET display_name = ? WHERE id = ?',
            (display_name, user_id)
        )
        self.db.commit()

        response = SecureResponseBuilder()
        response.set_status(200)
        response.set_header('X-Updated-User', display_name)
        response.set_json_body({'status': 'updated', 'display_name': display_name})
        return response

    def handle_redirect(self, token, ip, target_url):
        """Handle authenticated redirect."""
        user_id = self._authenticate(token, ip)
        if not user_id:
            return SecureResponseBuilder().set_status(401).set_json_body({'error': 'Unauthorized'})

        safe_url = validate_redirect_url(target_url, self.ALLOWED_HOSTS)
        if not safe_url:
            return SecureResponseBuilder().set_status(400).set_json_body({'error': 'Invalid redirect URL'})

        response = SecureResponseBuilder()
        response.set_status(302)
        response.set_header('Location', safe_url)
        response.set_json_body({'redirect': safe_url})
        return response

    def handle_export(self, token, ip, filename):
        """Handle data export with Content-Disposition."""
        user_id = self._authenticate(token, ip)
        if not user_id:
            return SecureResponseBuilder().set_status(401).set_json_body({'error': 'Unauthorized'})

        user = self._get_user(user_id)
        if not user:
            return SecureResponseBuilder().set_status(404).set_json_body({'error': 'User not found'})

        # Sanitize filename for Content-Disposition
        safe_filename = re.sub(r'[^a-zA-Z0-9._\-]', '_', filename) if filename else 'export.json'

        export_data = json.dumps({'user_id': user[0], 'email': user[1], 'display_name': user[2]})

        response = SecureResponseBuilder()
        response.set_status(200)
        response.set_header('Content-Disposition', f'attachment; filename="{safe_filename}"')
        response.set_header('Content-Type', 'application/json')
        response.body = export_data.encode('utf-8')
        return response
